// rust-01.rs —— 变量、可变性与所有权
// 运行：rustc --edition 2021 rust-01.rs -o rust-01 && ./rust-01
// 或把内容放进 src/main.rs 后 cargo run

#[derive(Debug, Clone, Copy)]
struct Point {
    x: i32,
    y: i32,
}

#[derive(Debug)]
struct Label {
    text: String,
}

struct Noisy(&'static str);

impl Drop for Noisy {
    fn drop(&mut self) {
        println!("drop {}", self.0);
    }
}

fn take(s: String) -> usize {
    s.len()
} // s 在这里 drop，堆缓冲区随之释放

fn peek(s: &str) -> usize {
    s.len()
} // 只借用，不负责释放

fn make_label(prefix: &str) -> Label {
    Label { text: format!("{prefix}-v1") }
}

fn main() {
    let mut count = 0;                     // mut：同一个绑定可以被赋值
    count += 1;
    let count = count * 10;                // shadowing：新绑定，旧值仍在
    let count = format!("count={count}");  // 还能换类型
    println!("{count}");                   // count=10

    let p = Point { x: 1, y: 2 };
    let q = p;                             // Point: Copy，按位复制
    println!("{} {} {}", p.x, p.y, q.x);   // 1 2 1

    let label = Label { text: String::from("rust") };
    let moved = label;                     // Label 含 String：移动，label 失效
    // println!("{}", label.text);         // E0382: borrow of moved value: `label`
    println!("{}", moved.text);            // rust

    let s = String::from("hello");
    let n = take(s);                       // 所有权进入 take
    // println!("{s}");                    // E0382: borrow of moved value: `s`
    println!("{n}");                       // 5

    let t = String::from("world");
    let m = peek(&t);                      // &String 自动退化为 &str
    println!("{m} {t}");                   // 5 world

    let owned = String::from("ownership");
    let slice: &str = &owned[..4];         // 借用堆缓冲区的前 4 字节
    println!("{slice} / {owned}");         // owne / ownership

    let l = make_label("note");
    println!("{l:?}");                     // Label { text: "note-v1" }

    println!("{}", peek("literal"));       // 7：字面量是 &'static str

    let _a = Noisy("a");
    let _b = Noisy("b");                   // 离开作用域时先 drop b，再 drop a
}

