// rust-02.rs —— 借用与生命周期
// 运行：rustc --edition 2021 rust-02.rs -o rust-02 && ./rust-02

#[derive(Debug)]
struct Excerpt<'a> {
    part: &'a str,
}

fn longest<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() >= y.len() { x } else { y }
}

fn first_word(s: &str) -> &str {
    s.split_whitespace().next().unwrap_or("")
}

fn static_msg() -> &'static str {
    "loaded from read-only data"
}

fn main() {
    let novel = String::from("Call me Ishmael. Some years ago...");
    let first = first_word(&novel);
    let excerpt = Excerpt { part: first };
    println!("part={} full={}", excerpt.part, novel); // part=Call full=Call me ...

    let a = String::from("long string is long");
    let b = String::from("xyz");
    println!("{}", longest(&a, &b));      // long string is long

    let mut v = vec![1, 2, 3];
    let head = &v[0];                     // 不可变借用开始
    println!("{head}");                   // 1，这是最后一次使用
    v.push(4);                            // NLL：借用已结束，允许可变借用
    println!("{v:?}");                    // [1, 2, 3, 4]

    let mut total = 0;
    {
        let r = &mut total;               // 独占借用
        *r += 10;
    }                                     // 作用域结束，借用归还
    println!("{total}");                  // 10

    let mut w = vec![1, 2, 3];
    // let x = &w[0];
    // w.push(4);                        // E0502：可变借用时仍有不可变借用
    // println!("{x}");
    w.push(4);
    println!("{w:?}");                    // [1, 2, 3, 4]

    println!("{}", static_msg());         // loaded from read-only data

    let leaked: &'static str = Box::leak(String::from("forever").into_boxed_str());
    println!("{leaked}");                 // forever，直到进程结束都不释放
}

