// rust-03.rs —— 结构体、枚举与模式匹配
// 运行：rustc --edition 2021 rust-03.rs -o rust-03 && ./rust-03

#[derive(Debug, Clone, PartialEq)]
enum State {
    Idle,
    Loading { progress: u8 },
    Ready { rows: usize },
    Failed(String),
}

#[derive(Debug)]
struct Job {
    id: u32,
    state: State,
}

impl Job {
    fn new(id: u32) -> Self {
        Self { id, state: State::Idle }
    }

    fn start(&mut self) {
        self.state = State::Loading { progress: 0 };
    }

    fn tick(&mut self, p: u8) {
        if let State::Loading { progress } = &mut self.state {
            *progress = (*progress).max(p.min(100));
        }
    }

    fn finish(&mut self, rows: usize) {
        self.state = State::Ready { rows };
    }

    fn describe(&self) -> String {
        match &self.state {
            State::Idle => format!("#{} idle", self.id),
            State::Loading { progress } => format!("#{} loading {progress}%", self.id),
            State::Ready { rows } => format!("#{} ready {rows} rows", self.id),
            State::Failed(msg) => format!("#{} failed: {msg}", self.id),
        }
    }
}

struct Meters(f64);
struct Marker;

#[derive(Debug)]
struct Config {
    host: String,
    port: u16,
}

fn parse_port(s: &str) -> Result<u16, String> {
    let n: u16 = s.parse().map_err(|_| format!("not a port: {s}"))?;
    if n == 0 {
        return Err(String::from("port 0 is reserved"));
    }
    Ok(n)
}

fn main() {
    let mut job = Job::new(7);
    println!("{}", job.describe());       // #7 idle
    job.start();
    job.tick(40);
    job.tick(20);                         // 不会让进度回退
    println!("{}", job.describe());       // #7 loading 40%
    job.finish(12);
    println!("{}", job.describe());       // #7 ready 12 rows

    let mut broken = Job::new(8);
    broken.state = State::Failed(String::from("disk full"));
    println!("{}", broken.describe());     // #8 failed: disk full

    for raw in ["8080", "0", "abc"] {
        match parse_port(raw) {
            Ok(p) => println!("{raw} -> {p}"),
            Err(e) => println!("{raw} -> err: {e}"),
        }
    }
    // 8080 -> 8080
    // 0 -> err: port 0 is reserved
    // abc -> err: not a port: abc

    if let Some(text) = Some("hello") {
        println!("if let: {text}");        // if let: hello
    }

    let maybe: Option<u8> = None;
    let Some(v) = maybe else {
        println!("let else: no value");    // 走这一支并离开 main
        return;
    };
    println!("{v}");

    let base = Config { host: String::from("localhost"), port: 80 };
    let dev = Config { port: 8080, ..base };
    println!("{}:{} -> {dev:?}", dev.host, dev.port);
    // localhost:8080 -> Config { host: "localhost", port: 8080 }
    // println!("{}", base.host);          // E0382：base.host 已被部分移动

    let m = Meters(1.5);
    println!("{} {}", m.0, std::mem::size_of::<Marker>()); // 1.5 0
}

