use std::fmt;

// 抽象：author 是必需能力，summarize 有默认实现。
trait Summary {
    fn author(&self) -> String;

    fn summarize(&self) -> String {
        format!("（作者：{}）", self.author())
    }
}

struct Article {
    title: String,
    author: String,
}

struct Tweet {
    user: String,
    #[allow(dead_code)] // 本示例只演示默认摘要，body 暂不读取
    body: String,
}

impl Summary for Article {
    fn author(&self) -> String {
        self.author.clone()
    }

    // 覆盖默认实现：文章有自己的摘要格式。
    fn summarize(&self) -> String {
        format!("《{}》——{}", self.title, self.author)
    }
}

impl Summary for Tweet {
    fn author(&self) -> String {
        format!("@{}", self.user)
    }
    // 不写 summarize，直接用默认实现。
}

// 静态分发：为每个具体类型生成一份 print_one。
fn print_one<T: Summary>(item: &T) {
    println!("{}", item.summarize());
}

// 动态分发：一份代码处理任意实现，调用走 vtable。
fn print_all(items: &[Box<dyn Summary>]) {
    for item in items {
        println!("{}", item.summarize());
    }
}

// 孤儿规则：不能 impl fmt::Display for Vec<String>，
// 但可以给本地 newtype 实现。
struct Tags(Vec<String>);

impl fmt::Display for Tags {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "#{}", self.0.join(" #"))
    }
}

fn main() {
    let article = Article {
        title: "Rust 的抽象方式".to_string(),
        author: "张三".to_string(),
    };
    let tweet = Tweet {
        user: "ferris".to_string(),
        body: "trait 不是 interface".to_string(),
    };

    print_one(&article);
    print_one(&tweet);

    let boxed: Vec<Box<dyn Summary>> = vec![
        Box::new(Article {
            title: "动态分发".to_string(),
            author: "李四".to_string(),
        }),
        Box::new(Tweet {
            user: "rustlang".to_string(),
            body: "vtable".to_string(),
        }),
    ];
    print_all(&boxed);

    println!("{}", Tags(vec!["rust".to_string(), "trait".to_string()]));
}

