use std::error::Error;
use std::fmt;
use std::num::ParseIntError;

// 应用层错误：调用方可以 match 出具体分支。
#[derive(Debug)]
enum ConfigError {
    MissingKey(&'static str),
    InvalidPort {
        key: &'static str,
        raw: String,
        source: ParseIntError,
    },
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::MissingKey(key) => write!(f, "缺少配置项 `{key}`"),
            ConfigError::InvalidPort { key, raw, .. } => {
                write!(f, "配置项 `{key}` 的值 `{raw}` 不是 0-65535 的整数")
            }
        }
    }
}

impl Error for ConfigError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            ConfigError::InvalidPort { source, .. } => Some(source),
            ConfigError::MissingKey(_) => None,
        }
    }
}

// 第二层错误：没有额外上下文，正好可以让 ? 自动 From。
#[derive(Debug)]
struct PortError(ParseIntError);

impl fmt::Display for PortError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "端口不是整数：{}", self.0)
    }
}

impl Error for PortError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        Some(&self.0)
    }
}

impl From<ParseIntError> for PortError {
    fn from(source: ParseIntError) -> Self {
        PortError(source)
    }
}

struct Config {
    host: String,
    port: u16,
}

// 只负责「找值」，不负责校验：返回借用，避免分配。
fn field<'a>(text: &'a str, key: &str) -> Option<&'a str> {
    text.lines()
        .find_map(|line| line.strip_prefix(key)?.strip_prefix('='))
        .map(str::trim)
}

fn parse_port_plain(raw: &str) -> Result<u16, PortError> {
    Ok(raw.parse::<u16>()?) // ? 在这里调用 From<ParseIntError>
}

fn parse_port(text: &str) -> Result<u16, ConfigError> {
    let raw = field(text, "PORT").ok_or(ConfigError::MissingKey("PORT"))?;
    raw.parse::<u16>().map_err(|source| ConfigError::InvalidPort {
        key: "PORT",
        raw: raw.to_string(),
        source,
    })
}

fn load(text: &str) -> Result<Config, ConfigError> {
    let host = field(text, "HOST")
        .ok_or(ConfigError::MissingKey("HOST"))?
        .to_string();
    let port = parse_port(text)?; // 同类型错误直接向上抛，不经过 From
    Ok(Config { host, port })
}

fn main() {
    println!("{:?}", parse_port_plain("8080")); // Ok(8080)

    let bad = "HOST=127.0.0.1\nPORT=80a";
    match load(bad) {
        Ok(cfg) => println!("启动于 {}:{}", cfg.host, cfg.port),
        Err(err) => {
            eprintln!("加载配置失败：{err}");
            // 沿 source 链打印根因：给人看的最后一层。
            let mut current = err.source();
            while let Some(cause) = current {
                eprintln!("  原因：{cause}");
                current = cause.source();
            }
        }
    }
}

