use std::collections::BTreeMap;
use std::sync::{mpsc, Arc, Mutex};
use std::thread;

fn main() {
    let text = "rust makes concurrency safe rust makes systems fast rust";
    let words: Vec<String> = text.split_whitespace().map(str::to_string).collect();

    // 共享计数：Arc 负责多所有者，Mutex 负责互斥写。
    let shared: Arc<Mutex<BTreeMap<String, usize>>> =
        Arc::new(Mutex::new(BTreeMap::new()));
    let (tx, rx) = mpsc::channel::<(usize, BTreeMap<String, usize>)>();

    let mut handles = Vec::new();
    for (idx, chunk) in words.chunks(2).enumerate() {
        let shared = Arc::clone(&shared);
        let tx = tx.clone();
        let local_words = chunk.to_vec();
        handles.push(thread::spawn(move || {
            let mut local: BTreeMap<String, usize> = BTreeMap::new();
            for word in &local_words {
                *local.entry(word.clone()).or_insert(0) += 1;
            }

            // 锁只包住真正写共享状态的那几行，guard 在块尾自动 drop。
            {
                let mut guard = shared.lock().expect("锁被毒化");
                for (word, count) in &local {
                    *guard.entry(word.clone()).or_insert(0) += count;
                }
            }

            // 把本线程的局部结果发回主线程，便于观察分片。
            tx.send((idx, local)).expect("主线程已退出");
        }));
    }

    drop(tx); // 关闭最后一个发送端，rx 的 for 才会结束

    let mut results: Vec<(usize, BTreeMap<String, usize>)> = rx.iter().collect();
    results.sort_by_key(|(idx, _)| *idx);
    for (idx, local) in results {
        println!("线程 {idx} 局部计数：{:?}", local);
    }

    for handle in handles {
        handle.join().expect("工作线程 panic");
    }

    let totals = shared.lock().expect("锁被毒化");
    println!("总计：{:?}", *totals);
}

