// Cargo.toml
// [package]
// name = "iter-closure"
// version = "0.1.0"
// edition = "2021"
//
// [dependencies]
// # 本节只用标准库，不需要任何第三方 crate
//
// 运行：cargo run --quiet

use std::cell::Cell;

#[derive(Debug)]
struct Entry {
    path: String,
    status: u16,
    ms: u64,
}

/// 手写迭代器：按行切分，全程零分配。
struct Lines<'a> {
    rest: &'a str,
}

impl<'a> Iterator for Lines<'a> {
    type Item = &'a str;

    fn next(&mut self) -> Option<&'a str> {
        let rest = self.rest; // 先拷出 &'a str，返回值才不用借用 self
        if rest.is_empty() {
            return None;
        }
        match rest.find('\n') {
            Some(i) => {
                self.rest = &rest[i + 1..];
                Some(rest[..i].trim_end_matches('\r'))
            }
            None => {
                self.rest = "";
                Some(rest) // 最后一行可能没有换行符
            }
        }
    }
}

/// 解析失败、空行、字段不足都返回 None，由 filter_map 丢弃。
fn parse(line: &str) -> Option<Entry> {
    let mut parts = line.split_whitespace();
    let _method = parts.next()?;
    let path = parts.next()?.to_string();
    let status = parts.next()?.parse::<u16>().ok()?;
    let ms = parts.next()?.parse::<u64>().ok()?;
    Some(Entry { path, status, ms })
}

/// 返回迭代器而不是 Vec：由调用方决定什么时候停。
fn slow<'a>(entries: &'a [Entry], min_ms: u64) -> impl Iterator<Item = &'a Entry> + 'a {
    entries.iter().filter(move |e| e.ms >= min_ms)
}

fn apply_twice<F: FnMut(i32) -> i32>(mut f: F, mut x: i32) -> i32 {
    x = f(x);
    f(x)
}

fn consume<F: FnOnce() -> String>(f: F) -> String {
    f()
}

fn main() {
    const RAW: &str = "GET /api/users 200 12\nGET /api/orders 500 320\nPOST /api/pay 201 45\nPOST /api/pay 502 910\nGET /api/search 200 640\nGET /api/pay 404 58\n";

    let entries: Vec<Entry> = Lines { rest: RAW }.filter_map(parse).collect();
    println!("entries = {}", entries.len()); // entries = 6

    // 只构造、不消费：next 一次都不会被调用
    let polls = Cell::new(0usize);
    let chain = entries.iter().inspect(|_| polls.set(polls.get() + 1));
    println!("构造后 polls = {}", polls.get()); // 构造后 polls = 0
    let n = chain.count();
    println!("count 后 polls = {}, n = {}", polls.get(), n); // polls = 6, n = 6

    let total: u64 = entries.iter().map(|e| e.ms).sum();
    let worst = entries.iter().fold(0u64, |acc, e| acc.max(e.ms));
    println!("total_ms = {}, worst_ms = {}", total, worst); // 1985, 910

    let errors: Vec<&Entry> = entries.iter().filter(|e| e.status >= 400).collect();
    println!("errors = {}", errors.len()); // errors = 3

    let slow_paths: Vec<&str> = slow(&entries, 300).map(|e| e.path.as_str()).collect();
    println!("slow_paths = {:?}", slow_paths); // ["/api/orders", "/api/pay", "/api/search"]

    // collect 到 Result：遇到第一个 Err 立即停止
    let parsed: Result<Vec<u16>, _> = ["200", "404", "x", "500"]
        .iter()
        .map(|s| s.parse::<u16>())
        .collect();
    match parsed {
        Ok(v) => println!("parsed = {:?}", v),
        Err(e) => println!("parsed 提前中断: {:?}", e.kind()), // InvalidDigit
    }

    // FnMut：闭包按可变借用捕获 step，所以能改外部变量
    let mut step = 3;
    let r = apply_twice(
        |x| {
            step += 1;
            x + step
        },
        10,
    );
    println!("apply_twice = {}, step = {}", r, step); // 19, 5

    // FnOnce：move 之后 name 的所有权归闭包，只能调用一次
    let name = String::from("inventory");
    let msg = consume(move || format!("处理 {} 完成", name));
    println!("{}", msg); // 处理 inventory 完成

    // 聚合：用 entry API，而不是 collect 出一个中间 Vec
    let mut buckets = std::collections::BTreeMap::new();
    for e in &entries {
        *buckets.entry(e.path.as_str()).or_insert(0usize) += 1;
    }
    for (path, count) in &buckets {
        println!("  {} -> {}", path, count); // /api/orders -> 1 等四行
    }
}

