// Cargo.toml
// [package]
// name = "async-tokio"
// version = "0.1.0"
// edition = "2021"
//
// [dependencies]
// tokio = { version = "1", features = ["full"] }
//
// 运行：cargo run --quiet

use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::time::Duration;

use tokio::time::{sleep, timeout};

/// 手工实现的 Future：第一次 poll 返回 Pending 并唤醒自己，第二次返回 Ready。
struct YieldNow(bool);

impl Future for YieldNow {
    type Output = ();

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        if self.0 {
            Poll::Ready(())
        } else {
            self.0 = true;
            cx.waker().wake_by_ref();
            Poll::Pending
        }
    }
}

/// 析构探针：用来证明 future 被 drop（取消）了。
struct Probe(&'static str);

impl Drop for Probe {
    fn drop(&mut self) {
        println!("[drop] {}", self.0);
    }
}

async fn job(name: &'static str, ms: u64) -> &'static str {
    let _probe = Probe(name);
    sleep(Duration::from_millis(ms)).await;
    println!("[done] {name}");
    name
}

#[tokio::main]
async fn main() {
    // 1) 惰性：构造 future 不执行函数体
    let fut = job("lazy", 10);
    println!("构造完 future，还没 await");
    drop(fut); // 函数体从未开始，Probe 也不会被构造

    // 2) 第一次 await 才开始跑：先 [done] A，再 [drop] A
    println!("A = {}", job("A", 30).await);

    // 3) join! 在同一任务里并发，总耗时接近较慢的那个
    let t0 = std::time::Instant::now();
    let (b, c) = tokio::join!(job("B", 50), job("C", 80));
    println!("join: {b} + {c}，用时约 {} ms", t0.elapsed().as_millis());

    // 4) timeout 只是不再等：内部 future 被 drop，Probe 跟着析构
    let t1 = std::time::Instant::now();
    match timeout(Duration::from_millis(40), job("slow", 200)).await {
        Ok(v) => println!("完成 {v}"),
        Err(_) => println!("超时，用时约 {} ms", t1.elapsed().as_millis()),
    }

    // 5) spawn：要求 Send + 'static，panic 会变成 JoinError
    let handle = tokio::spawn(async { job("spawned", 20).await });
    println!("主任务没有等 spawn");
    println!("spawn 结果 = {}", handle.await.expect("任务 panic"));

    // 6) 阻塞或 CPU 密集：进专用线程池，不占 worker
    let sum = tokio::task::spawn_blocking(|| (1u64..=1_000_000).sum::<u64>())
        .await
        .expect("阻塞任务 panic");
    println!("sum = {sum}"); // 500000500000

    // 7) 手写 Future 同样被 runtime 驱动
    YieldNow(false).await;
    println!("YieldNow 完成");
}

