// Cargo.toml
// [package]
// name = "axum-state"
// version = "0.1.0"
// edition = "2021"
//
// [dependencies]
// axum = "0.8"
// tokio = { version = "1", features = ["full"] }
// serde = { version = "1", features = ["derive"] }
// serde_json = "1"
//
// 运行：cargo run
// 另开终端：
//   curl -s localhost:3000/health
//   curl -s -X POST localhost:3000/items -H "Content-Type: application/json" -d '{"name":"keyboard","qty":3}'
//   curl -s localhost:3000/items/1
//   curl -s -o /dev/null -w "%{http_code}\n" localhost:3000/items/99
//   curl -s -o /dev/null -w "%{http_code}\n" -X POST localhost:3000/items      # 415
// 然后 Ctrl+C，观察先排空、再退出的日志顺序。

use std::collections::HashMap;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Instant;

use axum::extract::{Path, Request, State};
use axum::http::{HeaderValue, StatusCode};
use axum::middleware::{self, Next};
use axum::response::{IntoResponse, Response};
use axum::routing::get;
use axum::{Json, Router};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use tokio::sync::RwLock;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Item {
    id: u64,
    name: String,
    qty: u32,
}

#[derive(Debug, Deserialize)]
struct CreateItem {
    name: String,
    qty: u32,
}

/// 每个请求 clone 一份；真正的数据在 Arc 里。
#[derive(Clone)]
struct AppState {
    items: Arc<RwLock<HashMap<u64, Item>>>,
    next_id: Arc<AtomicU64>,
    req_seq: Arc<AtomicU64>,
    started: Instant,
}

impl AppState {
    fn new() -> Self {
        Self {
            items: Arc::new(RwLock::new(HashMap::new())),
            next_id: Arc::new(AtomicU64::new(0)),
            req_seq: Arc::new(AtomicU64::new(0)),
            started: Instant::now(),
        }
    }

    fn alloc_id(&self) -> u64 {
        self.next_id.fetch_add(1, Ordering::Relaxed) + 1
    }
}

/// 所有错误只有一个出口，handler 里只写 ?。
enum AppError {
    NotFound(u64),
    BadRequest(String),
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, msg) = match self {
            AppError::NotFound(id) => (StatusCode::NOT_FOUND, format!("item {id} not found")),
            AppError::BadRequest(m) => (StatusCode::BAD_REQUEST, m),
        };
        (status, Json(json!({ "ok": false, "error": msg }))).into_response()
    }
}

async fn health(State(state): State<AppState>) -> Json<Value> {
    let items = state.items.read().await.len();
    Json(json!({
        "ok": true,
        "uptime_s": state.started.elapsed().as_secs(),
        "items": items,
    }))
}

async fn list_items(State(state): State<AppState>) -> Json<Vec<Item>> {
    let mut items: Vec<Item> = state.items.read().await.values().cloned().collect();
    items.sort_by_key(|i| i.id);
    Json(items)
}

async fn get_item(State(state): State<AppState>, Path(id): Path<u64>) -> Result<Json<Item>, AppError> {
    let map = state.items.read().await;
    map.get(&id).cloned().map(Json).ok_or(AppError::NotFound(id))
}

async fn create_item(
    State(state): State<AppState>,
    Json(body): Json<CreateItem>,
) -> Result<(StatusCode, Json<Item>), AppError> {
    let name = body.name.trim().to_string();
    if name.is_empty() {
        return Err(AppError::BadRequest("name must not be empty".into()));
    }
    if body.qty == 0 {
        return Err(AppError::BadRequest("qty must be greater than 0".into()));
    }
    let item = Item {
        id: state.alloc_id(),
        name,
        qty: body.qty,
    };
    // 写锁在语句结束处释放，不跨 await
    state.items.write().await.insert(item.id, item.clone());
    Ok((StatusCode::CREATED, Json(item)))
}

async fn delete_item(
    State(state): State<AppState>,
    Path(id): Path<u64>,
) -> Result<StatusCode, AppError> {
    match state.items.write().await.remove(&id) {
        Some(_) => Ok(StatusCode::NO_CONTENT),
        None => Err(AppError::NotFound(id)),
    }
}

/// 中间件：先放行，拿到响应后再补头、再打日志。
async fn log_request(State(state): State<AppState>, req: Request, next: Next) -> Response {
    let method = req.method().clone();
    let path = req.uri().path().to_string();
    let start = Instant::now();
    let mut res = next.run(req).await;
    res.headers_mut()
        .insert("x-service", HeaderValue::from_static("inventory"));
    let seq = state.req_seq.fetch_add(1, Ordering::Relaxed) + 1;
    println!(
        "[req {seq}] {method} {path} -> {} ({} ms, 已运行 {} s)",
        res.status().as_u16(),
        start.elapsed().as_millis(),
        state.started.elapsed().as_secs()
    );
    res
}

async fn shutdown_signal() {
    tokio::signal::ctrl_c().await.expect("注册 Ctrl+C 失败");
    println!("收到 Ctrl+C，停止接受新连接，等待进行中的请求");
}

#[tokio::main]
async fn main() {
    let state = AppState::new();

    let app = Router::new()
        .route("/health", get(health))
        .route("/items", get(list_items).post(create_item))
        .route("/items/{id}", get(get_item).delete(delete_item))
        .layer(middleware::from_fn_with_state(state.clone(), log_request))
        .with_state(state.clone());

    let addr = "127.0.0.1:3000";
    let listener = tokio::net::TcpListener::bind(addr).await.expect("绑定 3000 失败");
    println!("listening on http://{addr}，Ctrl+C 触发优雅关闭");

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await
        .expect("server error");

    println!("连接已排空");
}

