// src/main.rs —— cargo new unsafe_demo 之后替换整个文件
// 运行：cargo run
// 查 UB：rustup component add miri && cargo +nightly miri run
use std::ffi::{CStr, CString};
use std::mem::MaybeUninit;
use std::os::raw::c_char;
use std::panic::{catch_unwind, AssertUnwindSafe};

/// 栈上定长缓冲区：只有 0..len 这段是初始化过的。
pub struct FixedBuf<const N: usize> {
    data: [MaybeUninit<u8>; N],
    len: usize,
}

impl<const N: usize> FixedBuf<N> {
    pub fn new() -> Self {
        // MaybeUninit<u8> 是 Copy，可以直接复制一份「未初始化」
        Self { data: [MaybeUninit::uninit(); N], len: 0 }
    }

    /// 写满就返回 false，绝不越界。
    pub fn push(&mut self, b: u8) -> bool {
        if self.len == N {
            return false;
        }
        self.data[self.len].write(b); // 安全方法：原地写入，不做任何读取
        self.len += 1;
        true
    }

    pub fn as_slice(&self) -> &[u8] {
        // SAFETY: MaybeUninit<u8> 与 u8 同布局；前 len 个元素都被 push 写过；
        // len 最多等于 N，所以指针范围始终在 data 之内。
        unsafe { std::slice::from_raw_parts(self.data.as_ptr().cast::<u8>(), self.len) }
    }
}

extern "C" {
    // 由 libc / msvcrt 提供：数到第一个 NUL 为止
    fn strlen(s: *const c_char) -> usize;
}

/// 安全封装：调用方不需要写 unsafe，也不需要知道 C 的约定。
fn c_strlen(s: &str) -> Option<usize> {
    // CString 保证末尾有且只有一个 NUL；含 NUL 的输入在这里变成 None
    let c = CString::new(s).ok()?;
    // SAFETY: c 活到本函数结束，as_ptr() 指向非空且以 NUL 结尾的有效内存。
    Some(unsafe { strlen(c.as_ptr()) })
}

/// 从 C 拿到的指针转成 Rust 的检查：先查空，再查 UTF-8。
fn c_strlen_borrowed(p: *const c_char) -> Option<usize> {
    if p.is_null() {
        return None; // CStr::from_ptr 要求非空
    }
    // SAFETY: 调用者保证 p 指向以 NUL 结尾、且本次调用期间有效的 C 字符串。
    let s = unsafe { CStr::from_ptr(p) };
    s.to_str().ok().map(|s| s.len())
}

/// # Safety
/// `ptr` 必须指向至少 `len` 个连续、已初始化的 u8，且本次调用期间不被其它线程改写。
#[no_mangle]
pub unsafe extern "C" fn sum_bytes(ptr: *const u8, len: usize) -> u64 {
    // from_raw_parts 要求指针非空且对齐，空切片也必须走这条路
    if ptr.is_null() || len == 0 {
        return 0;
    }
    let s = std::slice::from_raw_parts(ptr, len);
    s.iter().map(|&b| b as u64).sum()
}

/// 导出给 C 的入口：panic 绝不允许穿过 FFI 边界。
#[no_mangle]
pub extern "C" fn safe_entry(x: i32) -> i32 {
    let r = catch_unwind(AssertUnwindSafe(|| {
        if x < 0 {
            panic!("negative input");
        }
        x * 2
    }));
    r.unwrap_or(-1) // 用 -1 表达失败，调用方不必理解 Rust 的 panic
}

fn main() {
    let mut buf: FixedBuf<8> = FixedBuf::new();
    for b in b"rust" {
        buf.push(*b);
    }
    println!("buf = {:?}", std::str::from_utf8(buf.as_slice()).unwrap()); // "rust"

    let mut small: FixedBuf<2> = FixedBuf::new();
    small.push(1);
    small.push(2);
    println!("full = {}", small.push(3)); // false

    println!("len = {:?}", c_strlen("hello")); // Some(5)
    let bad = String::from_utf8(vec![b'h', 0, b'i']).unwrap();
    println!("nul = {:?}", c_strlen(&bad)); // None

    let owned = CString::new("hi").unwrap();
    println!("raw = {:?}", c_strlen_borrowed(owned.as_ptr())); // Some(2)

    // SAFETY: 字节数组在语句结束前一直存活，指针与长度匹配。
    let total = unsafe { sum_bytes(b"abcd".as_ptr(), 4) };
    println!("sum = {total}"); // 394

    // SAFETY: 空指针配 0 长度是函数内部专门处理的输入。
    println!("empty = {}", unsafe { sum_bytes(std::ptr::null(), 0) }); // 0

    println!("entry(-1) = {}", safe_entry(-1)); // -1，进程还活着
    println!("entry(21) = {}", safe_entry(21)); // 42
}

