// src/main.rs —— cargo run --release（Rust 2021，仅标准库）
// 说明：这里的计时只演示「怎么量」，真实基准请用 criterion。
use std::hint::black_box;
use std::time::Instant;

trait Area {
    fn area(&self) -> f64;
}

#[derive(Clone, Copy)]
struct Rect {
    w: f64,
    h: f64,
}

impl Area for Rect {
    fn area(&self) -> f64 {
        self.w * self.h
    }
}

#[derive(Clone, Copy)]
struct Circle {
    r: f64,
}

impl Area for Circle {
    fn area(&self) -> f64 {
        std::f64::consts::PI * self.r * self.r
    }
}

// 静态分发：每个具体类型各生成一份 total_static
fn total_static<T: Area>(items: &[T]) -> f64 {
    items.iter().map(|x| x.area()).sum()
}

// 动态分发：只生成一份，每次 area() 走一次 vtable
fn total_dynamic(items: &[Box<dyn Area>]) -> f64 {
    items.iter().map(|x| x.area()).sum()
}

// 一次分配：先算出总长度再开缓冲区
fn join_reserved(parts: &[&str]) -> String {
    let total: usize = parts.iter().map(|p| p.len()).sum();
    let mut out = String::with_capacity(total);
    for p in parts {
        out.push_str(p);
    }
    out
}

// 反复扩容：容量按翻倍增长，中间有多次重新分配 + 拷贝
fn join_grow(parts: &[&str]) -> String {
    let mut out = String::new();
    for p in parts {
        out.push_str(p);
    }
    out
}

// 跑 n 次取平均；black_box 阻止优化器把整个计算删掉
fn bench<F: FnMut() -> u64>(label: &str, n: u64, mut f: F) -> u64 {
    let start = Instant::now();
    let mut acc = 0u64;
    for _ in 0..n {
        acc ^= black_box(f());
    }
    let per = start.elapsed().as_nanos() as u64 / n;
    println!("{label:<20} {per:>8} ns/次   (acc={acc})");
    per
}

fn main() {
    let data: Vec<u64> = (1..=1000).collect();

    // 1. 迭代器链 vs 手写下标循环：release 下两者应该接近
    bench("iter.sum()", 1000, || data.iter().map(|&x| x * 2).sum::<u64>());
    bench("while + index", 1000, || {
        let mut s = 0u64;
        let mut i = 0;
        while i < data.len() {
            s += data[i] * 2;
            i += 1;
        }
        s
    });

    // 2. 容量预分配：结果相同，分配次数不同
    let parts: Vec<&str> = std::iter::repeat("chunk-").take(64).collect();
    bench("join_grow", 10_000, || join_grow(&parts).len() as u64);
    bench("join_reserved", 10_000, || join_reserved(&parts).len() as u64);

    // 3. 静态分发 vs 动态分发
    let rects = vec![Rect { w: 2.0, h: 3.0 }; 1000];
    bench("total_static", 10_000, || total_static(&rects) as u64);

    let mixed: Vec<Box<dyn Area>> = (0..1000)
        .map(|i| -> Box<dyn Area> {
            if i % 2 == 0 {
                Box::new(Rect { w: 2.0, h: 3.0 })
            } else {
                Box::new(Circle { r: 1.0 })
            }
        })
        .collect();
    bench("total_dynamic", 10_000, || total_dynamic(&mixed) as u64);

    // 4. 分配本身不便宜：clone 一整条 String
    let s = "x".repeat(4096);
    bench("clone 4KiB String", 100_000, || s.clone().len() as u64);
}

