// src/lib.rs —— cargo new --lib calc 之后替换本文件
// 运行：cargo test（单元测试 + 文档测试一起跑）
#![warn(missing_docs)]

//! 一个最小但完整的库：解析有符号整数，以及做饱和加法。
//!
//! 下面这个代码块就是文档测试，`cargo test` 会把它编译成
//! 独立 crate 并真的执行一遍：
//!
//! ```
//! use calc::{parse_i64, sat_add};
//! assert_eq!(parse_i64(" 42 "), Ok(42));
//! assert!(parse_i64("4 2").is_err());
//! assert_eq!(sat_add(i64::MAX, 1), i64::MAX);
//! ```

/// 解析失败时保留原始输入，方便上层拼出「哪个值错了」。
#[derive(Debug, PartialEq, Eq)]
pub struct ParseError(pub String);

/// 允许前后空白，但不允许中间有空白：`" 42 "` 合法，`"4 2"` 不合法。
pub fn parse_i64(s: &str) -> Result<i64, ParseError> {
    let t = s.trim();
    // map_err 丢掉 ParseIntError 的细节，只留下原始输入
    t.parse::<i64>().map_err(|_| ParseError(t.to_string()))
}

/// 溢出时贴边而不是回绕：对金额、计数一类的语义更安全。
pub fn sat_add(a: i64, b: i64) -> i64 {
    a.saturating_add(b)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn trims_surrounding_whitespace() {
        assert_eq!(parse_i64(" 7 "), Ok(7));
    }

    #[test]
    fn rejects_inner_whitespace() {
        let e = parse_i64("4 2").unwrap_err();
        assert_eq!(e.0, "4 2"); // 断言到具体内容，而不是只说「出错了」
    }

    #[test]
    fn saturates_at_both_ends() {
        assert_eq!(sat_add(i64::MAX, 1), i64::MAX);
        assert_eq!(sat_add(i64::MIN, -1), i64::MIN);
    }
}

